1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	// The spec does not define an output ordering, so full-result comparisons sort
5	// both sides first. Sorting is value-based, so a missing or extra cell still fails.
6	const sorted = (cells: Cell[]): Cell[] =>
7	  [...cells].sort(([x, y], [otherX, otherY]) => y - otherY || x - otherX);
8	
9	// The 2x2 block: every live cell has exactly 3 live neighbours, so the whole
10	// shape is a still life. Used by both the survival and the still-life tests.
11	const BLOCK: Cell[] = [
12	  [0, 0],
13	  [1, 0],
14	  [0, 1],
15	  [1, 1],
16	];
17	
18	describe("Game of Life - Next Generation", () => {
19	  it("should return an empty grid for an empty grid — [] -> []", () => {
20	    expect(nextGeneration([])).toEqual([]);
21	  });
22	
23	  it("should kill a single live cell with 0 neighbors (underpopulation) — [(0,0)] -> []", () => {
24	    expect(nextGeneration([[0, 0]])).toEqual([]);
25	  });
26	
27	  it("should kill both live cells when each has only 1 neighbor (underpopulation) — [(0,1), (1,1)] -> []", () => {
28	    expect(
29	      nextGeneration([
30	        [0, 1],
31	        [1, 1],
32	      ]),
33	    ).toEqual([]);
34	  });
35	
36	  // NOTE: the spec's Rule 2 illustration (`###`/`...`/`.#.` -> `.#.`/`.#.`/`...`)
37	  // is not reproducible under Conway's rules: its centre (1,1) is dead with 4
38	  // live neighbours, and the true next generation is [(1,-1),(0,1),(1,0),(2,1)].
39	  // The spec's *statement* of Rule 2 is sound, so we test that statement using
40	  // the block, where every live cell has exactly 3 neighbours and survives.
41	  it("should keep a live cell with 3 live neighbors alive (survival) — (0,0) of the block has 3 neighbors and survives", () => {
42	    expect(nextGeneration(BLOCK)).toContainEqual([0, 0]);
43	  });
44	
45	  // NOTE: as with Rule 2, the spec's Rule 3 illustration is inaccurate. In
46	  // `###`/`.#.`/`###` the centre (1,1) has 6 live neighbours, not the 4 the
47	  // prose claims, and the drawn Gen 1 (`#.#`/`#.#`/`#.#`) is not the true next
48	  // generation. The asserted *behaviour* is nonetheless correct: the centre is
49	  // overpopulated and dies, so we assert its absence rather than the drawing.
50	  it("should kill a live cell with 4 live neighbors (overpopulation) — center (1,1) of `###`/`.#.`/`###` dies", () => {
51	    const grid: Cell[] = [
52	      [0, 0],
53	      [1, 0],
54	      [2, 0],
55	      [1, 1],
56	      [0, 2],
57	      [1, 2],
58	      [2, 2],
59	    ];
60	
61	    expect(nextGeneration(grid)).not.toContainEqual([1, 1]);
62	  });
63	
64	  it("should bring a dead cell with exactly 3 live neighbors to life (reproduction) — (1,1) of `##.`/`#..`/`...` becomes alive", () => {
65	    const grid: Cell[] = [
66	      [0, 0],
67	      [1, 0],
68	      [0, 1],
69	    ];
70	
71	    expect(nextGeneration(grid)).toContainEqual([1, 1]);
72	  });
73	
74	  it("should keep a block unchanged (still life) — [(0,0), (1,0), (0,1), (1,1)] -> unchanged", () => {
75	    expect(sorted(nextGeneration(BLOCK))).toEqual(sorted(BLOCK));
76	  });
77	
78	  it("should turn a vertical blinker horizontal — [(0,0), (0,1), (0,2)] -> [(-1,1), (0,1), (1,1)]", () => {
79	    const vertical: Cell[] = [
80	      [0, 0],
81	      [0, 1],
82	      [0, 2],
83	    ];
84	    const horizontal: Cell[] = [
85	      [-1, 1],
86	      [0, 1],
87	      [1, 1],
88	    ];
89	
90	    expect(sorted(nextGeneration(vertical))).toEqual(sorted(horizontal));
91	  });
92	
93	  it.todo(
94	    "should turn the horizontal blinker back to vertical — [(-1,1), (0,1), (1,1)] -> [(0,0), (0,1), (0,2)]",
95	  );
96	
97	  it.todo(
98	    "should handle negative coordinates — a blinker at negative coordinates oscillates",
99	  );
100	});
